/* ---- self-check when the file is loaded: 5 exams x 50 questions x 5 strings, no duplicate options ---- */
(function () {
  var bad = [];
  for (var n = 1; n <= 5; n++) {
    var set = window.SK_EXAM_BANK[n] || [];
    if (set.length !== 50) bad.push('exam ' + n + ' has ' + set.length + ' questions');
    set.forEach(function (q, i) { if (!Array.isArray(q) || q.length !== 5 || new Set(q.slice(1)).size !== 4) bad.push('exam ' + n + ' q' + (i + 1)); });
  }
  window.SK_EXAM_BANK_OK = bad.length === 0;
  if (bad.length && typeof console !== 'undefined') console.warn('Exam bank problems:', bad);
})();
